						description:
							'Wrap an arbitrary () => Promise into a check. Resolves → pass; rejects → fail with the error message.',
						kind: 'value',
						name: 'probeCheck',
						signature:
							'const probeCheck: (name: string, probe: () => Promise<unknown> | unknown, options?: Omit<HealthCheckDefinition, "name" | "check">) => HealthCheckDefinition;'
